def test_r4_health_database_error_returns_503(client: TestClient, monkeypatch):
    """R4: Given unavailable backing database connection, GET /health returns 503."""
    class BrokenConnection:
        def __enter__(self):
            raise sqlite3.OperationalError("Database disk image is malformed")

        def __exit__(self, *args):
            pass

        def execute(self, *args, **kwargs):
            raise sqlite3.OperationalError("Database disk image is malformed")

        def cursor(self, *args, **kwargs):
            raise sqlite3.OperationalError("Database disk image is malformed")

        def commit(self, *args, **kwargs):
            raise sqlite3.OperationalError("Database disk image is malformed")

        def rollback(self, *args, **kwargs):
            pass

        def close(self, *args, **kwargs):
            pass

    def mock_db_failure(*args, **kwargs):
        raise sqlite3.OperationalError("Database disk image is malformed")

    monkeypatch.setattr(sqlite3, "connect", mock_db_failure)

    import app.database
    if hasattr(app.database, "sqlite3"):
        monkeypatch.setattr(app.database.sqlite3, "connect", mock_db_failure, raising=False)

    for attr in ["conn", "_conn", "connection", "_connection", "db", "_db"]:
        if hasattr(app.database, attr):
            monkeypatch.setattr(app.database, attr, BrokenConnection(), raising=False)

    if hasattr(app.database, "get_connection"):
        monkeypatch.setattr(app.database, "get_connection", lambda *args, **kwargs: BrokenConnection())

    if hasattr(app.database, "get_db"):
        monkeypatch.setattr(app.database, "get_db", mock_db_failure)
        client.app.dependency_overrides[app.database.get_db] = mock_db_failure

    import app.main
    if hasattr(app.main, "get_db"):
        client.app.dependency_overrides[app.main.get_db] = mock_db_failure

    for mod in [app.database, app.main, sys.modules.get("app.service")]:
        if not mod:
            continue
        for fn_name in ["check_db", "check_health", "check_db_health", "is_healthy", "health_check"]:
            if hasattr(mod, fn_name):
                monkeypatch.setattr(mod, fn_name, lambda *args, **kwargs: False, raising=False)

    try:
        response = client.get("/health")
        assert response.status_code == 503
        assert response.json().get("status") == "unhealthy"
    finally:
        client.app.dependency_overrides.clear()
