def test_r6_rate_limit_allows_requests_under_threshold(client: TestClient):
    """R6: Given client making requests below configured threshold, all succeed."""
    for i in range(5):
        res = client.post(
            "/shorten",
            json={"url": f"https://example.com/page{i}"},
            headers={"X-Forwarded-For": "198.51.100.1"},
        )
        assert res.status_code == 201


def test_r6_rate_limit_returns_429_and_retry_after(monkeypatch, isolated_db_path):
    """R6: Given client exceeding configured threshold, return HTTP 429 with Retry-After header."""
    monkeypatch.setenv("DATABASE_PATH", isolated_db_path)
    monkeypatch.setenv("RATE_LIMIT_REQUESTS", "3")
    monkeypatch.setenv("RATE_LIMIT_WINDOW_SECONDS", "60")

    if "app.config" in sys.modules:
        config_mod = sys.modules["app.config"]
        if hasattr(config_mod, "get_settings") and hasattr(config_mod.get_settings, "cache_clear"):
            config_mod.get_settings.cache_clear()
        if hasattr(config_mod, "settings"):
            monkeypatch.setattr(config_mod.settings, "RATE_LIMIT_REQUESTS", 3, raising=False)
            monkeypatch.setattr(config_mod.settings, "rate_limit_requests", 3, raising=False)

    try:
        import app.rate_limiter
        if hasattr(app.rate_limiter, "reset_rate_limiter"):
            app.rate_limiter.reset_rate_limiter()
        for attr in dir(app.rate_limiter):
            val = getattr(app.rate_limiter, attr)
            for lim_attr in ("max_requests", "requests_limit", "limit", "rate_limit"):
                if hasattr(val, lim_attr):
                    monkeypatch.setattr(val, lim_attr, 3, raising=False)
    except (ImportError, AttributeError):
        pass

    from app.main import app
    with TestClient(app, base_url="http://testserver") as rate_client:
        headers = {"X-Forwarded-For": "198.51.100.99"}

        res_blocked = None
        for i in range(70):
            res = rate_client.post("/shorten", json={"url": f"https://example.com/item{i}"}, headers=headers)
            if res.status_code == 429:
                res_blocked = res
                break
            assert res.status_code == 201

        assert res_blocked is not None, "Expected rate limit 429 response when threshold is exceeded"
        assert res_blocked.status_code == 429
        assert "retry-after" in [h.lower() for h in res_blocked.headers.keys()]
